package com.payroll.service; import com.payroll.model.Employee; import com.payroll.repository.EmployeeRepository; import org.junit.jupiter.api.Test; import org.mockito.Mockito; import java.math.BigDecimal; import java.time.LocalDate; import java.util.Optional; import static org.junit.jupiter.api.Assertions.assertThrows; import static org.mockito.Mockito.*; class EmployeeServiceTest { @Test void duplicateEmployeeCodeIsRejected(){EmployeeRepository r=mock(EmployeeRepository.class);AuditService a=mock(AuditService.class);when(r.findByEmployeeCode("EMP-1")).thenReturn(Optional.of(new Employee()));EmployeeService s=new EmployeeService(r,a);Employee e=new Employee("EMP-1","Test","test@example.test","9000000000","HR","Lead",BigDecimal.TEN,LocalDate.now());assertThrows(IllegalArgumentException.class,()->s.create(e,"admin"));verify(r,never()).save(any());} }